  methods: {
    detectDevice() {
        const userAgent = navigator.userAgent || navigator.vendor || window.opera;
        console.log(userAgent)
        // 检测iPhone
        if (/iPhone/.test(userAgent)) {
            return 'iPhone';
        }
        // 检测Android
        else if (/iPad/.test(userAgent)) {
            return 'iPad';
        }
        // 检测Android
        else if (/iPod/.test(userAgent)) {
            return 'iPod';
        }
        // 检测Android
        else if (/Android/.test(userAgent)) {
            return 'Android';
        }
        // 检测PC（主要是Chrome, Firefox, Safari等桌面浏览器）
        else if (!userAgent.match(/(iPhone|iPod|iPad|Android|BlackBerry|BB10|mobi|tablet|Opera Mini|IEMobile|WPDesktop)/)) {
            return 'PC';
        } else {
            return 'Unknown';
        }
    },
    getBrowserName() {
        var userAgent = navigator.userAgent;
        var browserName;
        if (userAgent.match(/MSIE|Trident/)) {
            browserName = "Internet Explorer";
        } else if (userAgent.match(/Firefox/)) {
            browserName = "Firefox";
        } else if (userAgent.match(/Chrome/)) {
            browserName = "Chrome";
        } else if (userAgent.match(/Safari/) && !userAgent.match(/Chrome/)) {
            browserName = "Safari";
        } else if (userAgent.match(/Opera|OPR/)) {
            browserName = "Opera";
        } else {
            browserName = "Unknown Browser";
        }
        return browserName;
