                title: item.gametypename
              }
            })
          } else {
            this.$router.push({
              path: '/detailView',
              query: {
                id: item.playtype
                // title: item.label
              }
            })
          }
        } else if (item.gametype > 910) {
          this.$toast(this.$t('home.sy42'))
        } else if (item.playtype) {
          // item.tkshow='0'
          if (item.tkshow === '0' && (localStorage.getItem('versionPop') !== item.version || localStorage.getItem('versionPop') === null)) {
            this.tkurl = item.tkurl
            this.showNoticePopTY = true
            localStorage.setItem('versionPop', item.version)
            this.currentItem = item
          } else {
            // this.goPlay(item)
            this.monType(item)
          }
        } else if (item.value) {
          if (item.value === 'gamePc28b' || item.value === 'gamePc28a') {
            this.$router.push({
              path: '/gameCanada',
              query: {
                id: item.value,
                title: item.label
              }
            })
          } else {
            this.$router.push({
              path: '/detailView',
              query: {
                id: item.value
              }
            })
          }
        } else {
          this.currentMenu = menuIndex
          this.currentGameMenuType = item.gamemenutype
          this.currentGameType = item.gametype
          window.scrollTo(0, 0)
          // this.$router.push({
          //   path: '/gameList',
          //   query: {
          //     gamemenutype: item.gamemenutype,
          //     gametype: item.gametype,
          //     isFirst: true
          //   }
          // })
        }
      } else {
        this.$toast(this.$t('bottomTab.zmk05'))
      }
    },
    goRouter(path) {
      if (this.$store.getters.token) {
        if (path === 'showShareBox') {
          this.showShareBox = true
        } else {
          this.$router.push({ path })
        }
      } else {
        this.$toast(this.$t('bottomTab.zmk05'))
      }
    },
    goRight() {
      const chatHistory = document.getElementById('tabs')
      chatHistory.scrollLeft = chatHistory.scrollWidth
    },
    // reach-bottom
    onReachBottom() {
      this.pageNum += 1
      this.getGoodsList()
    }
  }
}
</script>

