<script>
import bg from '@/assets/portal/logo2.png'
import QRCode from 'qrcodejs2'
import { shareother, shareown, getLogo } from '@/api/user'
import html2canvas from 'html2canvas'
import { Dialog } from 'vant'
export default {
  data() {
    return {
      shareurl: '',
      telurl: '',
      dataURL: '',
      imgBg: bg,
      inviteCode: '',
      beforeLoad: true,
      logoUrl: bg
    }
  },
  created() {
    // var link = document.getElementsByTagName('link')['longlogo']
    // this.logoUrl = link.href
    this.beforeLoad = false
  },
  mounted() {
    shareother().then(async res => {
      this.shareurl = res.shareurl
      this.telurl = res.telurl
      this.inviteCode = res.ucode
      var qrcode = new QRCode(this.$refs.qrcode, {
        text: this.shareurl, // xxx为设置要生成二维码的链接
        width: 144,
        height: 144,
        colorDark: '#000000',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.L,
        render: 'table'
      })
      // const a = await qrcode.toDataURL('image/png')
      this.$nextTick(() => {
        html2canvas(this.$refs.imageWrapper, {
          backgroundColor: null, // 解决生成会有白边的可能,但是没有遇到有白边,不知道有没有生效
          allowTaint: true, // 是否允许跨域图片(官方文档,代试验)
          useCORS: true,
          taintTest: true
          // scale: window.devicePixelRatio
        })
          .then(canvas => {
          // this.$refs.imageWrapper.appendChild(canvas)
            const dataURL = canvas.toDataURL('image/png')
            this.dataURL = dataURL
          // this.ready(dataURL)
          })
      })
      // setTimeout(() => {

      // }, 1000)
    })
  },
  methods: {
    async getApi() {
      await shareown()
      Dialog.alert({
        title: '提示',
        message: '您的邀请好友分享链接消息已推送至您的telegram账号'
      }).then(() => {
        // store.dispatch('user/resetToken').then(() => {
        //   router.push({ name: 'Login' })
        // })
      })
    },
    savePic() {
      // const dataURL = canvas.toDataURL('image/jpeg', 0.8)
      const link = document.createElement('a')
      link.href = this.dataURL
      link.download = 'poster.png'
      // 模拟点击链接，触发下载
      link.click()
    },
    openLink() {
      window.open(this.telurl)
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    },
    copyUrl(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }
}
</script>
