<template>
  <div class="gameListModules">
    <!-- <title-line :go-home="true" :title="title" /> -->
    <div class="gameContent">
      <!-- <div class="filter">
        <div class="filter-box" @click="showPop=!showPop">
          <div class="text">{{ gameTypeList.find(item=>item.gametype===currentValue).gametypename }}</div>
          <div class="drow_icon" />
        </div>
      </div> -->
      <title-line v-if="isHideTop" :title="titleText" :is-hide-top="true" />
      <div class="searchSpan">
        <div v-if="showSearch" class="search">
          <van-search
            v-model="searchText"
            :placeholder="$t('home.sy28')"
            left-icon=""
            color="#fff"
            @search="onSearch()"
            @focus="clickStatus=true"
            @blur="clickStatus=false"
            @clear="onCancel"
          >
            <template #right-icon>
              <div @click="onSearch">
                <div class="search_btn" />
              </div>
            </template>
          </van-search>
        </div>
        <div v-if="!showSearch" class="second-menu">
          <div v-if="gamemenutype !== '998' && gamemenutype !== '999' && gamemenutype !== '888'" class="navList">
            <div v-for="(item,index) in gameTypeList" :key="index" :class="currentTab===index?'nav active':'nav'" @click="item.status==='1'?showTip():tabClick(item,index)">
              <!-- <div :class="currentTab===index?'typeName active':'typeName'">{{ item.gametypename }}</div> -->
              <div class="logo" :style="{'background-image': 'url('+(currentTab===index?item.smallurl:item.activeurl)+')'}" />
            </div>
          </div>
        </div>
        <div class="searchBtn">
          <div v-if="showSearch" @click="showSearch=false">{{ $t('home.sy41') }}</div>
          <div v-if="!showSearch" @click="showSearch=true"><div class="search_btn" /></div>
          <div />
        </div>
      </div>

      <div />
      <div v-if="gamemenutype==='998'" class="box">
        <div v-for="(item,index) in typeList1" :key="index" class="wrapItem" :style="index===7?'margin-left:-10%':''" @click="goDetail(item)">
          <image-pic fill :radius="14" height="100%" width="100%" style="height:100%;width:100%;border-radius:14px;" :src="item.imgUrl" alt="" />
        </div>
      </div>
      <div v-else-if="gamemenutype==='999'" class="box">
        <div v-for="(item,index) in typeList2" :key="index" class="wrapItem" :style="index===7?'margin-left:-10%':''" @click="goDetail(item)">
          <image-pic fill :radius="14" height="100%" width="100%" style="height:100%;width:100%;border-radius:14px;" :src="item.imgUrl" alt="" />
        </div>
      </div>
      <div v-else class="box">
        <div v-for="(item,index) in playGameList" :key="index" :class="Number(playGameList.length) % 3 === 2?'wrapItem2':'wrapItem'" @click="showPopNotice(item)">
          <image-pic fill height="100%" width="100%" style="height:100%;width:100%;" :src="item.playtypeurl_webp" alt="" />
        </div>
      </div>
    </div>
    <van-popup
      v-model="showPop"
      closeable
      round
      close-icon="close"
      position="bottom"
      :style="{ height: 'auto' }"
    >
      <div class="popupTitle">{{ $t('home.sy27') }}</div>
      <div class="filterBox">
        <div v-for="(item,index) in gameTypeList" :key="item.gametype" :class="item.gametype===currentValue?'filterItem filterItemActive':'filterItem'" @click="tabClick(item,index)">
          <div class="text">{{ item.gametypename }}</div>
        </div>
      </div>
    </van-popup>
    <van-popup v-model="showNoticePopTY">
      <notice-pop-t-y :tkurl="tkurl" @close="showNoticePopTY=false;goPlay(currentItem)" />
    </van-popup>
    <van-popup v-if="showNoticePopSetmonstype" v-model="showNoticePopSetmonstype">
      <notice-pop-setmonstype :current-gametype="currentGametype" @goGameEvent="closeAndGoGame" @close="showNoticePopSetmonstype=false" />
    </van-popup>
  </div>
</template>
<script>
import NoticePopSetmonstype from './NoticePopSetmonstype'
import NoticePopTY from './NoticePopTY'
import TitleLine from './TitleLine'
import { getGameLsitbyown, getGameplayHotList } from '@/api/game'
import { getGameplayList, getgamechiprate, gotoGame } from '@/api/user'
import hxyx_1 from '@/assets/portal/home/hxyx_1.png'
import hxyx_2 from '@/assets/portal/home/hxyx_2.png'
import hxyx_3 from '@/assets/portal/home/hxyx_3.png'
import hxyx_4 from '@/assets/portal/home/hxyx_4.png'
import hxyx_5 from '@/assets/portal/home/hxyx_5.png'
import hxyx_6 from '@/assets/portal/home/hxyx_6.png'
import hxyx_7 from '@/assets/portal/home/hxyx_7.png'
import hxyx_8 from '@/assets/portal/home/hxyx_8.png'
import hxyx_101 from '@/assets/portal/home/hxyx_101.png'
import hxyx_102 from '@/assets/portal/home/hxyx_102.png'
import hxyx_103 from '@/assets/portal/home/hxyx_103.png'
import hxyx_104 from '@/assets/portal/home/hxyx_104.png'
import hxyx_105 from '@/assets/portal/home/hxyx_105.png'
import hxyx_106 from '@/assets/portal/home/hxyx_106.png'
import hxyx_107 from '@/assets/portal/home/hxyx_107.png'
import hxyx_108 from '@/assets/portal/home/hxyx_108.png'
import active_nav_all from '@/assets/portal/active-nav-all.png'
import nav_all from '@/assets/portal/nav-all.png'
export default {
  components: {
    NoticePopTY,
    NoticePopSetmonstype,
    TitleLine
  },
  props: {
    gamemenutype: {
      type: String,
      default: ''
    },
    gametype: {
      type: String,
      default: ''
    },
    isHideTop: {
      type: Boolean,
      default: false
    },
    titleText:{
      type: String,
      default: '热门'
    }
  },
  data() {
    return {
      showSearch: false,
      tkurl: '',
      currentItem: null,
      showNoticePopTY: false,
      showNoticePopSetmonstype: false,
      currentGametype: '',
      clickStatus: false,
      currentValue: '888',
      showPop: false,
      title: '电子游戏',
      searchText: '',
      currentTab: 0,
      // gamemenutype: '1',
      redbaghbid: null,
      gameTypeList: [],
      // gameTypeList: [{ activeurl: active_nav_all, gamemenutype: '888', gametype: '888', gametypename: '热门游戏', gametypeurl: 'https://img.rr888.vip/img/ztb-dtqp.jpg', order: '', smallurl: nav_all, status: '0' }],
      playGameList: [],
      allGameList: [],
      typeList1: [{
        imgUrl: hxyx_8, label: '哈希综合',
        value: 'gameZH'
      }, {
        imgUrl: hxyx_2, label: '哈希单双',
        value: 'gameSP'
      }, {
        imgUrl: hxyx_1, label: '哈希大小',
        value: 'gameDX'
      }, {
        imgUrl: hxyx_5, label: '哈希牛牛',
        value: 'gameBull'
      }, {
        imgUrl: hxyx_4, label: '哈希庄闲',
        value: 'gameZX'
      }, {
        imgUrl: hxyx_3, label: '幸运哈希',
        value: 'gameXY'
      }, {
        imgUrl: hxyx_6, label: '骰子单双',
        value: 'gameDiceSP'
      }, {
        imgUrl: hxyx_7, label: '骰子大小',
        value: 'gameDiceDX'
      }

      ],
      typeList2: [{
        imgUrl: hxyx_108, label: '哈希1分综合',
        value: 'gameMinuZH'
      }, {
        imgUrl: hxyx_102, label: '哈希1分单双',
        value: 'gameMinuSP'
      }, {
        imgUrl: hxyx_101, label: '哈希1分大小',
        value: 'gameMinuDX'
      }, {
        imgUrl: hxyx_105, label: '哈希1分牛牛',
        value: 'gameMinuBull'
      }, {
        imgUrl: hxyx_103, label: '哈希1分幸运',
        value: 'gameMinuXY'
      }, {
        imgUrl: hxyx_104, label: '哈希1分庄闲',
        value: 'gameMinuZX'
      }, {
        imgUrl: hxyx_106, label: '骰子1分单双',
        value: 'gameMinuDiceSP'
      }, {
        imgUrl: hxyx_107, label: '骰子1分大小',
        value: 'gameMinuDiceDX'
      }
      ],
      // titleText: '热门游戏'
    }
  },
  watch: {
    async gamemenutype(newVal) {
      debugger
      if (newVal === '888') {
        this.showSearch = true
      } else {
        this.showSearch = false
      }
      this.token = this.$store.getters.token
      // if (this.$route.query.gamemenutype) {
      //   this.gamemenutype = this.$route.query.gamemenutype
      //   this.title = this.gamemenutype === '1' ? this.$t('wdsr.wdsr40') : (this.gamemenutype === '2' ? this.$t('wdsr.wdsr41') : (this.gamemenutype === '3' ? this.$t('wdsr.wdsr42') : this.$t('wdsr.wdsr43')))
      // }
      if (newVal !== '998' && newVal !== '999' && newVal !== '888' && newVal !== '000') {
        const res = await getGameplayList({ gamemenutype: newVal })
        debugger
        this.gameTypeList = res.datalist
        const index = this.gameTypeList.findIndex(item => item.gametype === this.gametype)
        this.currentTab = index > 0 ? index : 0
        await this.$nextTick()
        const navList = document.getElementsByClassName('navList')
        const navWidth = document.getElementsByClassName('nav')[0].clientWidth
        navList[0].scroll({
          top: 0,
          left: (this.currentTab - 2) * navWidth,
          behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
        })
        this.loadGame(index > 0 ? this.gametype : this.gameTypeList[0].gametype, newVal)
      } else {
        this.loadGame(null, newVal)
      }
    }
  },
  async mounted() {
    if (this.gamemenutype === '888') {
      this.showSearch = true
    } else {
      this.showSearch = false
    }
    this.token = this.$store.getters.token
    // this.titleText = this.gamemenutype === '1' ? this.$t('wdsr.wdsr40') : (this.gamemenutype === '2' ? this.$t('wdsr.wdsr41') : (this.gamemenutype === '3' ? this.$t('wdsr.wdsr42') : (this.gamemenutype === '4' ? this.$t('wdsr.wdsr43') : this.$t('wdsr.wdsr53'))))
    if (this.$route.query.gamemenutype) {
      this.gamemenutype = this.$route.query.gamemenutype
      this.title = this.gamemenutype === '1' ? this.$t('wdsr.wdsr40') : (this.gamemenutype === '2' ? this.$t('wdsr.wdsr41') : (this.gamemenutype === '3' ? this.$t('wdsr.wdsr42') : this.$t('wdsr.wdsr43')))
    }
    if (this.gamemenutype !== '998' && this.gamemenutype !== '999' && this.gamemenutype !== '888' && this.gamemenutype !== '000') {
      const res = await getGameplayList({ gamemenutype: this.gamemenutype })
      debugger
      this.gameTypeList = res.datalist
      const index = this.gameTypeList.findIndex(item => item.gametype === this.gametype)
      this.currentTab = index > 0 ? index : 0
      await this.$nextTick()
      const navList = document.getElementsByClassName('navList')
      const navWidth = document.getElementsByClassName('nav')[0].clientWidth
      navList[0].scroll({
        top: 0,
        left: (this.currentTab - 2) * navWidth,
        behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
      })
      this.loadGame(index > 0 ? this.gametype : this.gameTypeList[0].gametype, this.gamemenutype)
    } else {
      this.loadGame(null, this.gamemenutype)
    }
  },
  methods: {
    onCancel() {
      this.playGameList = this.allGameList
    },
    async tabClick(item, index) {
      this.currentTab = index
      this.currentValue = item.gametype
      this.showPop = false
      await this.$nextTick()
      const navList = document.getElementsByClassName('navList')
      const navWidth = document.getElementsByClassName('nav')[0].clientWidth
      navList[0].scroll({
        top: 0,
        left: (this.currentTab - 2) * navWidth,
        behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
      })
      this.loadGame(item.gametype, item.gamemenutype)
    },
    async loadGame(gametype, gamemenutype) {
      if (gamemenutype !== '998' && gamemenutype !== '999' && gamemenutype !== '888' && gamemenutype !== '000') {
        const res = await getGameLsitbyown({ gametype: gametype, gamemenutype: gamemenutype })
        this.playGameList = res.datalist
        this.allGameList = res.datalist
      } else if (gamemenutype === '888') {
        const res = await getGameplayHotList()
        this.playGameList = res.datalist
        this.allGameList = res.datalist
      } else if (Number(gametype) > 900) {
        this.showTip()
      }
    },
    showPopNotice(item) {
      debugger
      if(item.gamemenutype === '995' && item.gametype==='74'){
        this.$router.push({path:'/iframeGame',query:{url:item.directurl.split('&')[0]}})
      }else if (item.gamemenutype === '995' && item.playtype) {
        if (item.playtype === 'gameHKlhc') {
          this.$router.push({
            path: '/gameHKlhc',
            query: {
              id: item.playtype,
              title: item.gametypename,
              gamemenutype:this.gamemenutype,
              gametype:item.gametype
            }
          })
        } else if (item.playtype === 'gamePc28b' || item.playtype === 'gamePc28a') {
          this.$router.push({
            path: '/gameCanada',
            query: {
              id: item.playtype,
              title: item.gametypename||item.playname,
              gamemenutype:this.gamemenutype,
              gametype:item.gametype
            }
          })
        } else {
          this.$router.push({
            path: '/detailView',
            query: {
              id: item.playtype,
              gamemenutype:this.gamemenutype,
              gametype:item.gametype
              // title: item.label
            }
          })
        }
      } else if (item.tkshow === '0' && (localStorage.getItem('versionPop') !== item.version || localStorage.getItem('versionPop') === null)) {
        this.tkurl = item.tkurl
        this.showNoticePopTY = true
        localStorage.setItem('versionPop', item.version)
        this.currentItem = item
      } else {
        this.monType(item)
      }
    },
    async monType(item) {
      try {
        const res = await getgamechiprate({ gametype: item.gametype });
           // res.ischipalert = '1'
        if (res.ischipalert === '1') {
          this.currentGametype = item.gametype
          this.showNoticePopSetmonstype = true
          this.currentItem = item
        } else {
          this.goPlay(item)
        }
      } catch (error) {
        console.log(error);
      }
    },
    closeAndGoGame(chiptype, savedays) {
      this.showNoticePopSetmonstype = false
      this.currentItem.chiptype = chiptype
      this.currentItem.savedays = savedays
      setTimeout(() => {
        this.goPlay(this.currentItem)
      }, 100)
    },
    async goPlay(item) {
      if (!item.chiptype) {
        try {
           const res = await getgamechiprate({ gametype: item.gametype })
           item.chiptype = res.chiptype
        } catch (error) {
          console.log(error);
        }
      }
      if (!item.savedays) {
        item.savedays = '0'
      }
      // if(item.gametype==='2'&&item.gamemenutype==='1'){
      //   gotoGame({ gametype: item.gametype, playtype: item.playtype }).then(res => {
      //     window.localStorage.removeItem('callbackHTML')
      //     window.localStorage.setItem('callbackHTML', res.gohtml)
      //     const newWin = window.open('', '_blank')
      //     newWin.document.write(localStorage.getItem('callbackHTML'))
      //   })
      // }else{
        setTimeout(() => {
          if (item.gamemenutype === '910' && item.isdirect === '1') {
            window.open(item.directurl)
          } else {
            window.open(process.env.VUE_APP_BASE_API + '/game/gotoGame?gametype=' + item.gametype + '&chiptype=' + item.chiptype + '&savedays=' + item.savedays + '&playtype=' + item.playtype + '&suid=' + this.$store.getters.token + '&visitorId=' + localStorage.getItem('visitorId') + '&suidvisitorid=' + this.$store.getters.token + localStorage.getItem('visitorId'))
          }
        }, 100)
      // }
    },
    showTip() {
      this.$toast(this.$t('home.sy42'))
    },
    onSearch() {
      debugger
      if (this.searchText) {
        this.playGameList = this.allGameList.filter(item => item.playname.includes(this.searchText))
      } else {
        this.loadGame(this.gameTypeList[this.currentTab].gametype, this.gameTypeList[this.currentTab].gamemenutype)
      }
    }
  }
}
</script>
