<template>
  <div class="menu" id="sidebar">
    <van-tabs v-model="active" type="card" @click="handleClick">
      <van-tab v-for="(item,index) in menuList" :key="index">
        <template #title>
          <svg-icon v-if="item.gamemenutype==='000'||item.gamemenutype==='888'" :icon-class="active==index ? item.activeurl : item.gametypeurl" :width="14" :height="14" style="padding-right:4px" />
          <img v-else :src="active==index ? item.activeurl : item.gametypeurl" alt="" style="height:14px;width:14px;padding-right:4px">
          {{ item.gamemenuname }}
        </template>
      </van-tab>
    </van-tabs>
  </div>
</template>
<script>
import { gethomeGameList, getUInfoByToken } from '@/api/user'
import { fpjsGetVisitorDataExtendedMixin } from '@fingerprintjs/fingerprintjs-pro-vue-v2'
export default {
  mixins: [fpjsGetVisitorDataExtendedMixin],
  props: {
    currentMenu: {
      type: String,
      default: null
    }
  },
  data() {
    return {
      active: 0,
      menuList: [
        {
          gamemenuname: this.$t('bottomTab.zmk01'),
          // path: '/newHome',
          activeurl: 'tab_首页_s'+ process.env.VUE_APP_BASE_THEME,
          gametypeurl: 'tab_首页_n',
          gamemenutype: '000'
        },
        {
          gamemenuname: this.$t('home.sy40'),
          icon: 'el-icon-s-home',
          // path: '/newGameList',
          activeurl: 'tab_热门_s'+process.env.VUE_APP_BASE_THEME,
          gametypeurl: 'tab_热门_n',
          gamemenutype: '888'
        }
      ]
    }
  },
  watch: {
    async currentMenu(val) {
      if(this.menuList.length<3){
        const res = await gethomeGameList()
        if(this.menuList.length<3){
          this.menuList = this.menuList.concat(res.datalist)
        }
      }
      // await this.$nextTick()
      this.active = this.menuList.findIndex(obj => obj.gamemenutype === val)
      this.handleClick()
    }
  },
  async created() {
    if (!localStorage.getItem('visitorId')) {
      await this.$getVisitorDataExtended()
      const visitorId = this.visitorDataExtended?.data?.visitorId
      if (visitorId) {
        localStorage.setItem('visitorId', visitorId)
      }
    }
    // const res = await gethomeGameList()
    // this.menuList = this.menuList.concat(res.datalist)
    gethomeGameList().then(res => {
      if (res.datalist) {
        if(this.menuList.length<3){
          this.menuList = this.menuList.concat(res.datalist) // .filter(obj=>obj.gamemenutype!=='995')
        } 
      }
    })
    // getUInfoByToken().then(res => {
    //   if (res.datalist) {
    //     this.menuList.forEach(item => {
    //       const indexItem = res.datalist.findIndex(obj => obj.gamemenuname.includes(item.name))
    //       if (indexItem >= 0) {
    //         item.gamemenutype = res.datalist[indexItem].gamemenutype
    //       }
    //     })
    //   }
    // })
  },
  mounted() {
    this.$bus.$on('returnHot', () => {
      this.active = 0
      this.handleClick()
    })
    let threshold=0
    setTimeout(() => {
      threshold=document.getElementById('sidebar').offsetTop
    }, 2000)
    document.addEventListener('scroll', function() {
        var sidebar = document.getElementById('sidebar');
        var scrollPosition = window.scrollY || document.documentElement.scrollTop; // 获取滚动位置
        // var threshold = 50; // 定义触发置顶的滚动阈值
    
        if (scrollPosition > threshold) {
          sidebar&&sidebar.classList.add('menu-top'); // 添加置顶样式
        } else {
          sidebar&&sidebar.classList.remove('menu-top'); // 移除置顶样式
        }
    });
  },
  methods: {
    handleClick() {
      this.$emit('changeActive', this.menuList[this.active].gamemenutype, this.active)
      // this.$bus.$emit('showMenuPop', false)
    }
  },
  beforeDestroy() {
    this.$bus.$off('returnHot')
    document.removeEventListener('scroll', function() {
        var sidebar = document.getElementById('sidebar');
        var scrollPosition = window.scrollY || document.documentElement.scrollTop; // 获取滚动位置
        // var threshold = 50; // 定义触发置顶的滚动阈值
    
        if (scrollPosition > threshold) {
          sidebar&&sidebar.classList.add('menu-top'); // 添加置顶样式
        } else {
          sidebar&&sidebar.classList.remove('menu-top'); // 移除置顶样式
        }
    });
  }
}
</script>
<style lang="less">
.menu-top{
  position: fixed;
  top: 88px;
  background: #101D55;
  margin-left: -28px;
  padding-left: 28px;
  width: 722px !important;
}
.menu {
  // margin-top: 12px;
  // margin-bottom: 12px;
  // position: fixed;
  // top: 88px;
  z-index: 999;
  // backdrop-filter: blur(100px);
  width: 100%;
  .van-tabs--card > .van-tabs__wrap {
    margin-top: 12px;
    margin-bottom: 12px;
    height: 64px;
  }
  .van-tabs__nav--card {
    border: none;
    height: 64px;
    margin: 0px;
    .van-tab {
      border-right: none;
    }
  }
  .van-tabs__nav {
    background:none;
    .van-tab {
      font-family: PingFangSC-Regular;
      font-size: 24px;
      color: #B2B3BF;
      font-weight: 400;
      // width: 144px;
      padding: 0 16px;
    }
    .van-tab--active {
      background: rgba(255,255,255,0.12);
      border-radius: 12px;
      font-family: PingFangSC-Semibold;
      font-size: 24px;
      color: #fff;
      font-weight: 600;
    }
    .van-tab__text {
      display: flex;
      align-items: center;
    }
  }
}
</style>
