<script>
// import { getLogo } from '@/api/user'
export default {
  props: {
    amount: {
      type: String,
      default: ''
    },
    isrmbxltzurl: {
      type: String,
      default: ''
    },
    isrmbxltz: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      showSelectBox: false,
      beforeLoad: true,
      login: false,
      logoUrl: ''
      // amount: 8.93
    }
  },
  watch: {
    '$store.getters.token'(val) {
      if (val) {
        this.login = true
      }
    }
  },
  created() {
    var link = document.getElementsByTagName('link')['longlogo']
    this.logoUrl = link.href
    this.beforeLoad = false
  },
  mounted() {
    if (this.$store.getters.token) {
      this.login = true
    } else {
      this.login = false
    }
  },
  methods: {
    openLink() {
      window.open(this.isrmbxltzurl)
    },
    showLogin() {
      this.$emit('showLogin', true)
    },
    showRegistry() {
      this.$emit('showRegistry', true)
    },
    showLanguage() {
      this.$emit('showLanguage', true)
    },
    showCustomer() {
      this.$bus.$emit('showCustomer', true)
    },
    onSearch() {
      this.$router.push({
        path: '/search'
      })
    },
    onUser() {
      this.$router.push({
        path: '/user'
      })
    },
    updateAmount() {
      this.$emit('updateAmount')
      this.$refs.update.classList.add('left-leave')
      setTimeout(() => {
        this.$refs.update.classList.remove('left-leave')
      }, 500)
    }
  }
}
</script>

