<template>
  <swiper
    ref="cardSwiper"
    class="swiper home_swiper"
    :options="swiperOptions"
    :space-between="30"
    slides-per-view="auto"
    :pagination="{ clickable: true }"
    @slideChange="cardChange()"
    @click-slide="onClick"
  >
    <swiper-slide v-for="(item, index) in bannerList" :key="index" class="slide">
      <img class="swiper_slide_bg" :src="item.imgUrl">
    </swiper-slide>
    <div slot="pagination" class="swiper-pagination" />
  </swiper>
</template>

<script>
export default {
  props: {
    bannerList: {
      type: Array,
      default() {
        return []
      }
    }
  },
  data() {
    return {
      swiperOptions: {
        direction: 'horizontal',
        loop: true,
        autoplay: {
          delay: 3000,
          disableOnInteraction: false
        },
        pagination: {
          el: '.swiper-pagination',
          clickable: true
        }
      },
      viplist: []
    }
  },
  async mounted() {
  },
  methods: {
    async cardChange() {
      const bullets = document.getElementsByClassName('swiper-pagination-bullet')
      for (let i = 0; i < bullets.length; i++) {
        bullets[i].innerHTML = ''
        if (this.$refs.cardSwiper.$swiper.activeIndex === bullets.length + 1) {
          bullets[0].innerHTML = '<div class="anim-circle"></div>'
        } else if (i === this.$refs.cardSwiper.$swiper.activeIndex - 1) {
          bullets[i].innerHTML = '<div class="anim-circle"></div>'
        }
      }
    },
    onClick(index1, index) {
      const item = this.bannerList[index]
      if (this.$store.getters.token) {
        if (item.isgo === '1') {
          if (item.gourl) {
          // window.open(item.gourl, '_self ')
            window.location.href = item.gourl
          } else if (item.jumpUrl) {
            this.$router.push({ path: item.jumpUrl })
          }
        }
      } else {
        this.$toast(this.$t('bottomTab.zmk05'))
      }
    }
  }
}
</script>

<style lang="scss">
@keyframes move{0%{width:0}to{width:100%}}
.home_swiper {
  .van-image__img{
    border-radius: 18px;
  }
  .van-image{
    border-radius: 18px;
  }
            padding-bottom: 48px;
            line-height: 1.5;
            .swiper_slide_bg {
                position: absolute;
                z-index: -1;
                width: 100%;
                height: 100%;
                border-radius: 18px;
            }
            .slide{
              border-radius: 18px;
              // margin:20px 0;
              height:308px;
                // width:588px;
                // height: 352px;
                // margin-right: 32px;
                .vip_swiper_item {
                  border-radius: 18px;
                  position: relative;
                  display: flex;
                  flex-direction: column;
                  justify-content: flex-end;
                  height: 260px;
                    // width: 588px;

                }
            }
            .swiper-pagination-bullet {
                background: rgba(255,255,255,0.8);
                height: 12px;
                width: 24px;
                border-radius: 12px;
                margin: 0 12px;
            }
            .swiper-pagination-bullet-active {
                width: 80px;
                border-radius: 8px;
                background: rgba(255,255,255,0.2);
                // opacity: 0.2;
            }
            .anim-circle{
              width: 80px;
              height: 100%;
              border-radius: 8px;
              background: var(--btn-bg-color);
              animation: 3s move linear;
              z-index: 99999;
            }
        }
</style>
